export const CSS_SOURCE = "/*\n * @typstream/html-compat: styles for the HTML that html-compat.typ emits, and Typst-like\n * defaults for the elements Typst's HTML export writes natively (tables, math).\n *\n * Everything is scoped to the renderer's root element, `.typstream`, and wrapped in\n * :where() so an app's own rules win without !important. Inline `style` attributes\n * carry the per-element values from the document (sizes, colors, strokes).\n */\n\n/* Top-level place() is positioned against the document. */\n:where(.typstream) {\n  position: relative;\n}\n\n/* Block elements inside a box are spans (a div would end the paragraph); this makes them blocks.\n   Rules below that set another display (grid, flex) come later and win. */\n:where(.typstream .ts-b) {\n  display: block;\n}\n\n/* Math: Typst's own math font. Without a math font, browsers can't stretch delimiters\n   and fall back to whatever has the math alphanumerics (PLAN.md §6.5). */\n:where(.typstream) math {\n  /* biome-ignore lint/a11y/useGenericFontNames: `math` is the generic family (CSS Fonts 4). */\n  font-family: \"New Computer Modern Math\", math;\n}\n:where(.typstream) math[display=\"block\"] {\n  margin: 0.65em 0;\n}\n:where(.typstream .ts-equation) {\n  display: flex;\n  align-items: center;\n  gap: 1em;\n}\n:where(.typstream .ts-equation) > math {\n  flex: 1;\n}\n:where(.typstream .ts-equation) > p {\n  margin: 0;\n}\n\n/* Tables: Typst's defaults are a 1pt black stroke on every cell, start/top alignment and no\n   bold header. The cell's own padding, fill and alignment are on its .ts-cell. */\n:where(.typstream) table {\n  border-collapse: collapse;\n}\n:where(.typstream) :is(td, th) {\n  border: 1pt solid currentColor;\n  padding: 0;\n  vertical-align: top;\n  text-align: start;\n  font-weight: inherit;\n}\n:where(.typstream) :is(td, th):has(> .ts-no-stroke) {\n  border: none;\n}\n\n/* Layout containers. Blocks inside an align() move like its text. */\n:where(.typstream .ts-align-center) > * {\n  margin-inline: auto;\n}\n:where(.typstream) :is(.ts-align-end, .ts-align-right) > * {\n  margin-inline-start: auto;\n}\n:where(.typstream .ts-grid) {\n  display: grid;\n}\n:where(.typstream .ts-cell) {\n  min-width: 0;\n  box-sizing: border-box;\n}\n:where(.typstream .ts-valign) {\n  display: flex;\n  flex-direction: column;\n}\n:where(.typstream .ts-stack) {\n  display: flex;\n}\n:where(.typstream .ts-columns) {\n  column-fill: balance;\n}\n:where(.typstream .ts-colbreak) {\n  break-after: column;\n}\n:where(.typstream .ts-pagebreak) {\n  break-after: page;\n  border-top: 1px dashed color-mix(in srgb, currentColor 25%, transparent);\n  margin: 1.5em 0;\n}\n\n/* Boxes and blocks. Typst draws strokes centred on the edge and counts them in the size. */\n:where(.typstream) :is(.ts-block, .ts-shape, .ts-box, .ts-place) {\n  box-sizing: border-box;\n}\n:where(.typstream) :is(.ts-block, .ts-shape) {\n  position: relative;\n  margin-block: 0.6em;\n}\n/* Typst spaces blocks apart, not from the edges of what contains them. */\n:where(.typstream)\n  :is(.ts-cell, .ts-block, .ts-shape, .ts-box, .ts-stack-item, .ts-place, .ts-align, figure)\n  > :first-child {\n  margin-block-start: 0;\n}\n:where(.typstream)\n  :is(.ts-cell, .ts-block, .ts-shape, .ts-box, .ts-stack-item, .ts-place, .ts-align, figure)\n  > :last-child {\n  margin-block-end: 0;\n}\n:where(.typstream .ts-box) {\n  display: inline-block;\n  position: relative;\n  vertical-align: baseline;\n}\n/* box(width: 1fr) takes the rest of a line in Typst; HTML has no inline equivalent. */\n:where(.typstream .ts-box.ts-fr) {\n  min-width: 4em;\n  overflow: hidden;\n  white-space: nowrap;\n  vertical-align: bottom;\n}\n:where(.typstream .ts-repeat) {\n  white-space: nowrap;\n}\n/* Empty shapes are drawings of a size; with content they size to it. */\n:where(.typstream .ts-shape:empty) {\n  min-height: 1em;\n}\n:where(.typstream .ts-line) {\n  height: 0;\n  margin: 0.6em 0;\n}\n:where(.typstream .ts-transform) {\n  width: fit-content;\n}\n:where(.typstream .ts-hide) {\n  visibility: hidden;\n}\n\n/* place(): absolute, against the nearest block, shape or box (or the document). */\n:where(.typstream .ts-place) {\n  position: absolute;\n}\n:where(.typstream .ts-place.ts-float) {\n  position: static;\n}\n\n/* Spacing. */\n:where(.typstream .ts-h) {\n  display: inline-block;\n}\n:where(.typstream .ts-hfill) {\n  display: inline-block;\n  width: 2em;\n}\n\n/* Enumerations with a numbering pattern carry their markers as text. */\n:where(.typstream .ts-enum) {\n  list-style: none;\n  padding-inline-start: 1.5em;\n}\n:where(.typstream .ts-enum) > li > .ts-marker {\n  display: inline-block;\n  min-width: 1.5em;\n  margin-inline-start: -1.5em;\n}\n\n/* Drawings (html.frame): inline SVG, scaled down to fit narrow containers. */\n:where(.typstream .ts-frame) svg {\n  max-width: 100%;\n  height: auto;\n}\n:where(.typstream) :is(div.ts-frame, span.ts-frame.ts-b) {\n  width: fit-content;\n  margin-block: 0.6em;\n}\n";
